"""Strict additive source guard. Not runtime or visual acceptance."""
from pathlib import Path
import hashlib
import unittest
ROOT = Path(__file__).resolve().parents[2]

class OrdinaryLogAgainSourceTests(unittest.TestCase):
    def test_only_additive_prefill_and_consumer_wiring_changed(self):
        source = (ROOT / 'Ate/Views/NutritionDiaryView.swift').read_text()
        self.assertEqual(source.count("    /// Reuse only the person's saved snapshot. Identity, date and selected meal\n    /// remain this new form's; no persistence or catalogue verification is implied.\n    private func repeatFood(_ food: NutritionFrequentFood) {\n        guard existing == nil else { return }\n        let draft = NutritionFrequentFoods.draft(from: food, dayKey: dayKey)\n        foodName = draft.foodName\n        quantity = draft.quantity\n        quantityUnit = draft.quantityUnit\n        servings = draft.servings\n        source = draft.source\n        sourceName = draft.sourceName\n        sourceIdentifier = draft.sourceIdentifier\n        verificationNote = draft.verificationNote\n        nutrientText = draft.nutrientText\n        errorMessage = nil\n        focusedField = nil\n    }\n\n"), 1)
        source = source.replace("    /// Reuse only the person's saved snapshot. Identity, date and selected meal\n    /// remain this new form's; no persistence or catalogue verification is implied.\n    private func repeatFood(_ food: NutritionFrequentFood) {\n        guard existing == nil else { return }\n        let draft = NutritionFrequentFoods.draft(from: food, dayKey: dayKey)\n        foodName = draft.foodName\n        quantity = draft.quantity\n        quantityUnit = draft.quantityUnit\n        servings = draft.servings\n        source = draft.source\n        sourceName = draft.sourceName\n        sourceIdentifier = draft.sourceIdentifier\n        verificationNote = draft.verificationNote\n        nutrientText = draft.nutrientText\n        errorMessage = nil\n        focusedField = nil\n    }\n\n", "", 1)
        self.assertEqual(source.count('            if existing == nil && !frequentFoods.isEmpty {\n                Section {\n                    DisclosureGroup("Log again") {\n                        ForEach(Array(frequentFoods.enumerated()), id: \\.offset) { index, food in\n                            Button { repeatFood(food) } label: {\n                                HStack {\n                                    Text(food.foodName)\n                                    Spacer()\n                                    Text("logged \\(food.timesLogged)x")\n                                        .font(AteFont.body(12)).foregroundStyle(Theme.mutedForeground)\n                                }\n                                .frame(minHeight: 44)\n                                .contentShape(Rectangle())\n                            }\n                            .buttonStyle(.plain)\n                            .accessibilityLabel("Log \\(food.foodName) again")\n                            .accessibilityHint("Fills this form from your last entry. Review and save to log it.")\n                            .accessibilityIdentifier("nutritionDiary.frequent.\\(index)")\n                        }\n                        Text("From your own entries. Values copy as last logged, not as verified nutrition. Review them before saving; nothing is logged until you tap Save.")\n                            .font(AteFont.body(12)).foregroundStyle(Theme.mutedForeground)\n                    }\n                    .accessibilityIdentifier("nutritionDiary.frequentChoices")\n                }\n            }\n'), 1)
        source = source.replace('            if existing == nil && !frequentFoods.isEmpty {\n                Section {\n                    DisclosureGroup("Log again") {\n                        ForEach(Array(frequentFoods.enumerated()), id: \\.offset) { index, food in\n                            Button { repeatFood(food) } label: {\n                                HStack {\n                                    Text(food.foodName)\n                                    Spacer()\n                                    Text("logged \\(food.timesLogged)x")\n                                        .font(AteFont.body(12)).foregroundStyle(Theme.mutedForeground)\n                                }\n                                .frame(minHeight: 44)\n                                .contentShape(Rectangle())\n                            }\n                            .buttonStyle(.plain)\n                            .accessibilityLabel("Log \\(food.foodName) again")\n                            .accessibilityHint("Fills this form from your last entry. Review and save to log it.")\n                            .accessibilityIdentifier("nutritionDiary.frequent.\\(index)")\n                        }\n                        Text("From your own entries. Values copy as last logged, not as verified nutrition. Review them before saving; nothing is logged until you tap Save.")\n                            .font(AteFont.body(12)).foregroundStyle(Theme.mutedForeground)\n                    }\n                    .accessibilityIdentifier("nutritionDiary.frequentChoices")\n                }\n            }\n', "", 1)
        self.assertEqual(source.count('    let frequentFoods: [NutritionFrequentFood]\n'), 1)
        source = source.replace('    let frequentFoods: [NutritionFrequentFood]\n', "", 1)
        self.assertEqual(source.count('         frequentFoods: [NutritionFrequentFood] = [],\n'), 1)
        source = source.replace('         frequentFoods: [NutritionFrequentFood] = [],\n', "", 1)
        self.assertEqual(source.count('        self.frequentFoods = frequentFoods\n'), 1)
        source = source.replace('        self.frequentFoods = frequentFoods\n', "", 1)
        self.assertEqual(source.count('NutritionDiaryEntryForm(date: selectedDate, dayKey: selectedDayKey,\n                                         frequentFoods: NutritionFrequentFoods.topFoods(in: entries)) { entry in'), 1)
        source = source.replace('NutritionDiaryEntryForm(date: selectedDate, dayKey: selectedDayKey,\n                                         frequentFoods: NutritionFrequentFoods.topFoods(in: entries)) { entry in', 'NutritionDiaryEntryForm(date: selectedDate, dayKey: selectedDayKey) { entry in', 1)
        self.assertEqual(hashlib.sha256(source.encode()).hexdigest(), 'aad00c4c2e9b937290aad67be831163fca99157738680de3a94b1f87cc3ff6b6')

    def test_shared_snapshot_helper_is_unchanged(self):
        self.assertEqual(hashlib.sha256((ROOT / 'Ate/Logic/NutritionFrequentFoods.swift').read_bytes()).hexdigest(), '7aca8168bb86bd1db1542e80833b62bcdc407c5d124c9aa0b36dfd3c9dc645aa')

    def test_native_reuse_journey_preserves_cancel_save_and_reload_assertions(self):
        source = (ROOT / 'AteUITests/NutritionLogAgainUITests.swift').read_text()
        for required in ['XCTAssertEqual(rows(app).count, 1', 'XCTAssertEqual(rows(app).count, 2',
                         'app.terminate()', 'Selecting must not save or dismiss',
                         'ordinary-log-again-offer', 'ordinary-log-again-prefilled',
                         'ordinary-log-again-saved-twice', 'ordinary-log-again-relaunched']:
            self.assertIn(required, source)
